<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Event,Show}; use Illuminate\Http\{JsonResponse,Request};
class CatalogApiController extends Controller { public function events(Request $r):JsonResponse{$q=Event::with('category')->where('status','published');if($r->filled('q'))$q->where(fn($x)=>$x->where('title','like','%'.$r->q.'%')->orWhere('summary','like','%'.$r->q.'%'));if($r->filled('type'))$q->where('type',$r->string('type'));if($r->filled('category_id'))$q->where('category_id',$r->integer('category_id'));if($r->filled('city'))$q->whereHas('shows.venue',fn($x)=>$x->where('city',$r->string('city')));if($r->filled('date'))$q->whereHas('shows',fn($x)=>$x->whereDate('starts_at',$r->date('date')));return response()->json($q->latest()->paginate(20)->withQueryString());} public function event(Event $event):JsonResponse{return response()->json($event->load('category','shows.venue'));} public function show(Show $show):JsonResponse{return response()->json($show->load('event','venue.seats'));} }
